import { randomFillSync, randomUUID } from 'crypto';

/**
 * Internal identifier types - generated by the system
 */
export type EventId = string & { readonly __brand: 'EventId' };
export type JobId = string & { readonly __brand: 'JobId' };
export type AggregateId = string & { readonly __brand: 'AggregateId' };
export type CorrelationId = string & { readonly __brand: 'CorrelationId' };
export type ObservationId = string & { readonly __brand: 'ObservationId' };
export type MediaId = string & { readonly __brand: 'MediaId' };
export type TokenId = string & { readonly __brand: 'TokenId' };
export type TokenArtworkId = string & { readonly __brand: 'TokenArtworkId' };
export type MarketSnapshotId = string & { readonly __brand: 'MarketSnapshotId' };
export type CreatorProfileId = string & { readonly __brand: 'CreatorProfileId' };

/**
 * External identifier types - received from providers
 */
export type ProviderId = string & { readonly __brand: 'ProviderId' };
export type ProviderReferenceId = string & { readonly __brand: 'ProviderReferenceId' };

const UUIDV7_COUNTER_MAX = 0xfff;
/**
 * Leaves 2048 slots of headroom in the same millisecond before the counter has
 * to borrow from the next one. Seeding randomly rather than from zero keeps two
 * processes starting in the same millisecond from colliding.
 */
const UUIDV7_COUNTER_SEED_MASK = 0x7ff;

let lastMs = -1;
let counter = 0;

/**
 * Generate a UUIDv7 (RFC 9562 §5.7): a 48-bit big-endian Unix millisecond
 * timestamp, then version 7, then a 12-bit counter, then the variant and 62
 * random bits.
 *
 * TIS ch.2 §2 requires v7 for primary domain entities, and the reason is
 * physical rather than cosmetic. `observations`, `media`, `evidence` and
 * `domain_events` are large append-only tables (ch.2 §6 asks for them to be
 * partition-ready). A v4 key scatters every insert across the whole primary-key
 * B-tree, so the index working set grows with the table; a v7 key appends to the
 * rightmost leaf. It also makes the primary key sort chronologically, which is
 * what lets replay walk a table in ingestion order without a secondary index.
 *
 * Values are monotonic within a process: the counter increments for repeated
 * calls inside one millisecond, and a clock that steps backwards is pinned to
 * the last millisecond already used rather than emitting a lower value. Both
 * matter because ordering by id is only meaningful if id order matches
 * generation order.
 */
export function uuidv7(): string {
  const observed = Date.now();

  if (observed > lastMs) {
    lastMs = observed;
    counter = randomFillSync(Buffer.allocUnsafe(2)).readUInt16BE(0) & UUIDV7_COUNTER_SEED_MASK;
  } else {
    // Covers two cases with one branch: a second call inside the same
    // millisecond, and a clock that has gone backwards (NTP correction, VM
    // migration). Neither may produce a timestamp below one already issued.
    counter += 1;
    if (counter > UUIDV7_COUNTER_MAX) {
      // Out of counter space. Borrow the next millisecond rather than block;
      // the value stays ordered and is at most a millisecond ahead of the clock.
      lastMs += 1;
      counter = 0;
    }
  }

  const bytes = Buffer.allocUnsafe(16);
  bytes.writeUIntBE(lastMs, 0, 6);
  // Version nibble (0x7) in the high 4 bits, counter in the low 12.
  bytes.writeUInt16BE(0x7000 | counter, 6);
  randomFillSync(bytes, 8, 8);
  // Variant: replace the top two bits of byte 8 with 0b10.
  bytes.writeUInt8((bytes.readUInt8(8) & 0x3f) | 0x80, 8);

  const hex = bytes.toString('hex');
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    hex.slice(12, 16),
    hex.slice(16, 20),
    hex.slice(20),
  ].join('-');
}

/** Milliseconds encoded in a UUIDv7's timestamp prefix. */
export function uuidv7Timestamp(id: string): number {
  return parseInt(id.slice(0, 8) + id.slice(9, 13), 16);
}

/**
 * Generate a new internal identifier
 *
 * Domain aggregates use v7 for the index-locality and ordering reasons above.
 * Events, jobs and correlation IDs stay on v4: `domain_events` is keyed by a
 * v7-ordered aggregate anyway, jobs are a bounded working set rather than an
 * append-only history, and a correlation ID is a label that should carry no
 * timestamp a log reader could mistake for the event time.
 */
export function generateEventId(): EventId {
  return randomUUID() as EventId;
}

export function generateJobId(): JobId {
  return randomUUID() as JobId;
}

export function generateAggregateId(): AggregateId {
  return uuidv7() as AggregateId;
}

export function generateCorrelationId(): CorrelationId {
  return randomUUID() as CorrelationId;
}

export function generateObservationId(): ObservationId {
  return uuidv7() as ObservationId;
}

export function generateMediaId(): MediaId {
  return uuidv7() as MediaId;
}

/**
 * Market identifiers, all v7 for the same reason observations are: `tokens`,
 * `market_snapshots` and `token_artwork` are append-heavy and read in
 * chronological order, which is exactly what a v7 key gives without a secondary
 * index. `creator_profiles` is the odd one — it is current state rather than
 * history — but a mixed convention inside one package costs more than the
 * locality it would save.
 */
export function generateTokenId(): TokenId {
  return uuidv7() as TokenId;
}

export function generateTokenArtworkId(): TokenArtworkId {
  return uuidv7() as TokenArtworkId;
}

export function generateMarketSnapshotId(): MarketSnapshotId {
  return uuidv7() as MarketSnapshotId;
}

export function generateCreatorProfileId(): CreatorProfileId {
  return uuidv7() as CreatorProfileId;
}

/**
 * Create external identifier from provider data
 */
export function createProviderId(id: string): ProviderId {
  return id as ProviderId;
}

export function createProviderReferenceId(id: string): ProviderReferenceId {
  return id as ProviderReferenceId;
}
